   891	/**
   892	 * Force-delete dependency report: what a hard delete of the tree removes or
   893	 * detaches. Computed up front so `dry_run` can return it without mutating and
   894	 * the real delete can echo exactly what it touched. Event rows are append-only
   895	 * and are only ever detached, never deleted.
   896	 */
   897	export interface ForceDeleteTreeReport {
   898	  entities: number;
   899	  relationships: number;
   900	  behaviors_deleted: number;
   901	  behaviors_detached: number;
   902	  feeds_deleted: number;
   903	  feeds_detached: number;
   904	  events_detached: number;
   905	}
