   994	          WHERE f.entity_ids && ${entityTreeIdsLiteral}::bigint[]
   995	            AND f.entity_ids <@ ${entityTreeIdsLiteral}::bigint[])::int AS feeds_deleted,
   996	        (SELECT COUNT(*) FROM feeds f
   997	          WHERE f.entity_ids && ${entityTreeIdsLiteral}::bigint[]
