  1006	      behaviors_detached: Number(preflight[0]?.behaviors_detached || 0),
  1007	      feeds_deleted: Number(preflight[0]?.feeds_deleted || 0),
  1008	      feeds_detached: Number(preflight[0]?.feeds_detached || 0),
  1009	      events_detached: Number(preflight[0]?.events_detached || 0),
