  1082	          FROM (
  1083	            SELECT w.id AS old_root
  1084	            FROM watchers w
  1085	            WHERE w.id = w.watcher_group_id
  1086	              AND w.entity_ids && ${entityTreeIdsLiteral}::bigint[]
  1087	              AND w.entity_ids <@ ${entityTreeIdsLiteral}::bigint[]
  1088	          ) r
  1089	          JOIN watchers s
  1090	            ON s.watcher_group_id = r.old_root
  1091	           AND s.id <> r.old_root
  1092	           AND NOT (
  1093	             COALESCE(s.entity_ids, '{}'::bigint[]) && ${entityTreeIdsLiteral}::bigint[]
  1094	             AND COALESCE(s.entity_ids, '{}'::bigint[]) <@ ${entityTreeIdsLiteral}::bigint[]
  1095	           )
  1096	           AND NOT EXISTS (
  1097	             SELECT 1 FROM watcher_versions vv WHERE vv.watcher_id = s.id
