   115				winnerId: params.winnerId,
   116				loserIds,
   117				expectedFingerprint: params.expectedResolutionFingerprint,
   118				// Computed by this process moments ago, so it is current by
   119				// construction — never a stored digest from an older format.
   120				expectedVersion: RESOLUTION_FINGERPRINT_VERSION,
