   165	  // Lock both rows in a stable order (lowest id first) to avoid deadlocks when
   166	  // two merges touch the overlapping pair concurrently.
   167	  const [a, b] = loserId < winnerId ? [loserId, winnerId] : [winnerId, loserId];
