   169	    id: number;
   170	    entity_type_id: number;
   171	    merged_into: number | null;
   172	    deleted_at: string | null;
   173			name: string;
   174			metadata: Record<string, unknown>;
   175			field_controls: Record<string, unknown>;
   176	  }>`
   177	    SELECT id, entity_type_id, merged_into, deleted_at, name, metadata, field_controls
   178	    FROM entities
   179	    WHERE organization_id = ${orgId} AND id IN (${a}, ${b})
   180	    ORDER BY id
   181	    FOR UPDATE
   182	  `;
   183	
   184	  const loser = locked.find((row) => Number(row.id) === loserId);
   185	  const winner = locked.find((row) => Number(row.id) === winnerId);
   186	  if (!loser || !winner) {
   187			throw new Error(
   188				`applyMerge: entity not found in org (loser=${loserId} winner=${winnerId})`,
   189			);
   190	  }
   191	  if (Number(loser.merged_into) === winnerId) {
   192	    return { movedIdentities: 0, repointedEdges: 0 };
   193	  }
   194	  if (loser.merged_into !== null) {
   195			throw new Error(
   196				`applyMerge: loser ${loserId} already merged into ${loser.merged_into}`,
   197			);
   198	  }
   199	  if (loser.deleted_at !== null) {
   200	    throw new Error(`applyMerge: loser ${loserId} is deleted`);
   201	  }
   202	  if (winner.merged_into !== null) {
   203			throw new Error(
   204				`applyMerge: winner ${winnerId} is itself merged into ${winner.merged_into}`,
   205			);
   206	  }
   207	  if (winner.deleted_at !== null) {
   208	    throw new Error(`applyMerge: winner ${winnerId} is deleted`);
   209	  }
   210	  if (Number(loser.entity_type_id) !== Number(winner.entity_type_id)) {
   211			throw new Error(
   212				"applyMerge: cannot merge entities of different entity types",
   213			);
   214	  }
   215	
   216		const identitiesBefore = await tx<{
   217			id: number;
   218			merged_from_entity_id: number | null;
   219		}>`
   220	    SELECT id, merged_from_entity_id
   221	    FROM entity_identities
   222	    WHERE organization_id = ${orgId}
   223	      AND entity_id = ${loserId}
   224	      AND deleted_at IS NULL
   225	    ORDER BY id
   226	    FOR UPDATE
   227	  `;
   228	
   229		const relationshipsBefore = await tx<{
   230			id: number;
   231			from_entity_id: number;
   232			to_entity_id: number;
   233			deleted_at: Date | string | null;
   234		}>`
   235	    SELECT id, from_entity_id, to_entity_id, deleted_at
   236	    FROM entity_relationships
   237	    WHERE organization_id = ${orgId}
   238	      AND deleted_at IS NULL
   239	      AND (from_entity_id = ${loserId} OR to_entity_id = ${loserId})
   240	    ORDER BY id
