   268				name: winner.name,
   269				metadata: winner.metadata ?? {},
   270				fieldControls: winner.field_controls ?? {},
   271			},
   272			{
   273				name: loser.name,
   274				metadata: loser.metadata ?? {},
   275				fieldControls: loser.field_controls ?? {},
   276			},
   277		);
