   280	    SET metadata = ${tx.json(mergedState.metadata)},
   281	        field_controls = ${tx.json(mergedState.fieldControls)},
   282	        updated_at = current_timestamp
   283	    WHERE id = ${winnerId} AND organization_id = ${orgId}
   284	  `;
