   292	    SET deleted_at = current_timestamp, updated_at = current_timestamp
   293	    WHERE r.organization_id = ${orgId}
   294	      AND r.deleted_at IS NULL
   295	      AND (r.from_entity_id = ${loserId} OR r.to_entity_id = ${loserId})
