   299	        OR EXISTS (
   300	          SELECT 1
   301	          FROM entity_relationships o
   302	          WHERE o.organization_id = ${orgId}
   303	            AND o.deleted_at IS NULL
   304	            AND o.id <> r.id
   305	            AND o.relationship_type_id = r.relationship_type_id
   306	            AND o.from_entity_id = CASE
   307	              WHEN r.from_entity_id = ${loserId} THEN ${winnerId}
   308	              ELSE r.from_entity_id
   309	            END
   310	            AND o.to_entity_id = CASE
   311	              WHEN r.to_entity_id = ${loserId} THEN ${winnerId}
   312	              ELSE r.to_entity_id
   313	            END
   314	        )
   315	      )
   316	  `;
   317	
   318	  // Repoint only the non-colliding live edges that remain.
   319	  const repointed = (await tx<{ id: number }>`
   320	    UPDATE entity_relationships
   321	    SET from_entity_id = CASE WHEN from_entity_id = ${loserId} THEN ${winnerId} ELSE from_entity_id END,
   322	        to_entity_id   = CASE WHEN to_entity_id   = ${loserId} THEN ${winnerId} ELSE to_entity_id   END,
   323	        updated_at = current_timestamp
   324	    WHERE organization_id = ${orgId}
   325	      AND deleted_at IS NULL
   326	      AND (from_entity_id = ${loserId} OR to_entity_id = ${loserId})
   327	    RETURNING id
   328	  `) as Array<{ id: number }>;
   329	
   330	  // 4. Flatten: anything that already pointed at the loser now points at the
   331	  //    winner, so every redirect stays exactly one hop (no chain walk at read).
   332	  //    The read redirect (`entity_ids && ARRAY(… merged_into = X …)`) is a
   333	  //    one-time indexed lookup even when X is an outer column, which a recursive
   334	  //    chain walk would NOT be on list/count/order call sites. The identities'
   335	  //    COALESCE'd `merged_from` markers (step 1) preserve reversibility that
   336	  //    the flattened `merged_into` pointer alone would lose.
   337		const redirected = await tx<{ id: number }>`
