   351		const relationshipIds = relationshipsBefore.map((row) => Number(row.id));
   352		const relationshipsAfter =
   353			relationshipIds.length > 0
   354				? await tx<{
   355						id: number;
   356						from_entity_id: number;
   357						to_entity_id: number;
   358						deleted_at: Date | string | null;
   359					}>`
   360	        SELECT id, from_entity_id, to_entity_id, deleted_at
   361	        FROM entity_relationships
   362	        WHERE organization_id = ${orgId}
   363	          AND id = ANY(${pgBigintArray(relationshipIds)}::bigint[])
   364	        ORDER BY id
   365	      `
