   395						toEntityId: Number(before.to_entity_id),
   396						deletedAt: timestamp(before.deleted_at),
   397					},
   398					after: {
   399						fromEntityId: Number(after.from_entity_id),
   400						toEntityId: Number(after.to_entity_id),
   401						deletedAt: timestamp(after.deleted_at),
   402					},
   403				};
   404			}),
   405		};
