   408	    INSERT INTO entity_merge_operations
   409	      (organization_id, winner_entity_id, loser_entity_id, source_run_id,
   410	       watcher_id, window_id, decision, policy_hash, evidence, ledger, merged_by)
   411	    VALUES
   412	      (${orgId}, ${winnerId}, ${loserId}, ${resolution.sourceRunId ?? null},
   413	       ${resolution.watcherId ?? null}, ${resolution.windowId ?? null},
   414	       ${resolution.decision}, ${resolution.policyHash ?? null},
   415	       ${tx.json(resolution.evidence ?? [])}, ${tx.json(ledger)}, ${mergedBy})
