   725	export async function enableClassifiersOnEntity(
   726		sql: DbClient,
   727		entityId: number,
   728		classifierSlugs: string[],
   729	): Promise<void> {
   730		if (classifierSlugs.length === 0) return;
   731	
   732		// Get current enabled classifiers
   733		const entity = await sql`
   734	    SELECT enabled_classifiers FROM entities WHERE id = ${entityId}
   735	  `;
   736	
   737		if (entity.length === 0) {
   738			logger.warn(`[ClassifierExtraction] Entity ${entityId} not found`);
   739			return;
   740		}
   741	
   742		// Parse PostgreSQL array (may come as string like "{urgency,team_routing}")
   743		const currentEnabled = parsePgTextArray(entity[0].enabled_classifiers);
   744		const toAdd = classifierSlugs.filter(
   745			(slug) => !currentEnabled.includes(slug),
   746		);
   747	
   748		if (toAdd.length === 0) return;
   749	
   750		// Compute combined array and set directly
   751		const combined = [...currentEnabled, ...toAdd];
   752		const arrayLiteral = pgTextArray(combined);
   753	
   754		await sql`
   755	    UPDATE entities
   756	    SET enabled_classifiers = ${arrayLiteral}::text[]
   757	    WHERE id = ${entityId}
   758	  `;
   759	
   760		logger.info(
   761			`[ClassifierExtraction] Enabled ${toAdd.length} classifier(s) on entity ${entityId}`,
   762		);
   763	}
