    14	 * Origin provenance (the window that first produced the entity, its stable key,
    15	 * and the watcher) is stamped onto the entity's own `metadata` at creation —
    16	 * `metadata.window_id` / `stable_key` / `watcher_id`. There is NO separate
    17	 * observation event: an entity is promoted once (it's an identity, not a time
    18	 * series), so its origin lives on the row itself.
    19	 *
    20	 * The upsert runs on the caller's transaction handle so the entity and identity
    21	 * writes commit atomically with the window itself.
    22	 *
    23	 * Multi-replica notes:
    24	 *   - `entities.id` / `entity_identities.id` are `nextval()` sequence columns,
    25	 *     so concurrent inserts never collide on the PK (no advisory-lock allocator
    26	 *     needed here — that's only for the MAX(id)+1 tables).
    27	 *   - The window (canvas chain root) is guarded by `idx_canvas_chain_root`, so at
    28	 *     most one completion creates a given window; idempotent replays reuse it and
    29	 *     re-enter this function, where the per-key identity claim makes repeats
    30	 *     no-ops.
    31	 *   - `fetch_types: false`: never bind a raw JS array — all identifiers here are
    32	 *     scalar params.
    33	 */
    34	
    35	import { slugify } from '@lobu/core';
    36	import { ApprovalAttribution } from '@lobu/core/contracts/interaction-envelope';
    37	import {
    38	  deferEntityCreate,
    39	  deferEntityFieldChange,
    40	  type DeferredMutation,
    41	  runMutationGate,
    42	} from '../authz/entity-mutation-gate';
    43	import {
    44	  mutationPrincipalId,
    45	  resolveWatcherOwner,
    46	} from '../authz/entity-policy';
    47	import type { DbClient } from '../db/client';
    48	import type { EntityOutput } from '../types/watchers';
    49	import {
    50	  type AppliedChange,
    51	  type BlockedChange,
    52	  mergeEntityFields,
    53	} from './entity-field-merge';
    54	import logger from './logger';
    55	import { isUniqueViolation } from './pg-errors';
    56	import { resolveEntityCreator } from './resolve-entity-creator';
    57	import { computeStableKey, formatBehaviorEntityIdentity } from './stable-keys';
    58	
    59	/** Namespace for the stable-key identity claim in `entity_identities`. */
    60	const WATCHER_KEY_NAMESPACE = 'watcher_key';
    61	
    62	/** Agent-authored field naming the content a promoted row came from. */
    63	const SOURCE_EVENT_ID_FIELD = 'source_event_id';
    64	
    65	export interface PromoteKeyedEntitiesParams {
    66	  /** Transaction-bound SQL handle (MUST be the window-write transaction). */
    67	  tx: DbClient;
    68	  /** Full extracted result containing this output's top-level array. */
    69	  extractedData: Record<string, unknown>;
    70	  outputName: string;
    71	  output: EntityOutput;
    72	  watcherId: number;
    73	  organizationId: string;
    74	  /** The finalized window identity (canvas ROOT event id) this completion produced/reused. */
    75	  windowId: number;
    76	  /**
    77	   * The exact content IDs the window_token granted for this completion.
    78	   * A promoted row may cite its origin via `source_event_id`; that value comes
    79	   * from agent output and is otherwise stored verbatim, so an agent could point
    80	   * a promotion at content its window never read. Citations outside this set are
    81	   * dropped (the row still promotes — only the unverifiable claim is removed).
    82	   */
    83	  validContentIds: Set<number>;
    84	  /** The watcher's bound parent entity (entity_ids[0]); null when unbound. */
    85	  parentEntityId: number | null;
    86	  /**
    87	   * Attribution for created entities — MUST be a live `user(id)` because
    88	   * `entities.created_by` is NOT NULL with an ON DELETE RESTRICT FK. The
    89	   * watcher's own `created_by` satisfies this. When null, an org owner/admin is
    90	   * resolved as a fallback; if none exists, entity creation is skipped.
    91	   */
    92	  createdBy?: string | null;
    93	}
    94	
    95	/**
    96	 * One entity this run touched inline, for the first-class run change-set. Emitted
    97	 * for auto-applied changes too — the diff is a property of the run, not of the
    98	 * approval flow, so a fully-auto watcher run still shows exactly what it changed.
    99	 */
   100	export interface PromotedEntityChange {
   101	  entityId: number;
   102	  name: string;
   103	  /** `created` = brand-new entity; `updated` = existing entity whose fields changed. */
   104	  kind: 'created' | 'updated';
   105	  /** For `updated`, the fields written inline (old→new). Empty for `created`. */
   106	  applied: Record<string, AppliedChange>;
   107	}
   108	
   109	export interface PromoteKeyedEntitiesResult {
   110	  /** Number of distinct keyed rows that resolved to an entity. */
   111	  promoted: number;
   112	  /** Of those, how many created a brand-new entity (vs. matched an existing). */
   113	  created: number;
   114	  /**
   115	   * Owned-field / policy-gated changes and policy-held creates that were NOT
   116	   * applied — packaged as deferred approvals the caller flushes POST-COMMIT
   117	   * (never writing inline, never on the caller's tx).
   118	   */
   119	  deferred: DeferredMutation[];
   120	  /**
   121	   * The applied change-set: every entity this run created or updated inline. The
   122	   * caller records this as a first-class event on the run so the change is
   123	   * visible on the run itself, independent of any approval.
   124	   */
   125	  changes: PromotedEntityChange[];
   126	}
   127	
   128	/**
   129	 * Build a human-readable entity name from RAW field values (not the slugified
   130	 * key). Falls back to the stable key when no field carries a value.
   131	 *
   132	 * Prefers `name_fields` and falls back to `key_fields`. The two are separate on
   133	 * purpose: a stable key must never change between runs, so it is usually an
   134	 * opaque id (`li_home_DijYQ…`), which makes a terrible display name. Keying on
   135	 * the readable field instead would tie the entity's identity to a value that can
   136	 * be edited upstream — a renamed author would orphan the entity and promote a
   137	 * duplicate.
   138	 */
   139	export function buildEntityName(
   140	  entityRecord: Record<string, unknown>,
   141	  output: EntityOutput,
   142	  stableKey: string
   143	): string {
   144	  const nameFields =
   145	    output.name && output.name.length > 0 ? output.name : output.key;
   146	  const parts = nameFields
   147	    .map((field) => entityRecord[field])
   148	    .filter((v): v is string | number => v !== null && v !== undefined && String(v).trim().length > 0)
   149	    .map((v) => String(v).trim());
   150	  const joined = parts.join(' · ');
   151	  return joined.length > 0 ? joined : stableKey;
   152	}
   153	
   154	/**
   155	 * Resolve an entity-type slug → entity_types(id), searching the watcher's own
   156	 * org first then any public catalog (same precedence as createEntity). Skips
   157	 * derived (view-backed) types — they have no stored rows to insert into.
   158	 */
   159	async function resolveEntityTypeId(
   160	  tx: DbClient,
   161	  organizationId: string,
   162	  entityTypeSlug: string
   163	): Promise<number | null> {
   164	  const rows = await tx<{ id: number; backing_sql: string | null }>`
   165	    SELECT et.id, et.backing_sql
   166	    FROM entity_types et
   167	    LEFT JOIN organization o ON o.id = et.organization_id
   168	    WHERE et.slug = ${entityTypeSlug}
   169	      AND et.deleted_at IS NULL
   170	      AND (
   171	        et.organization_id = ${organizationId}
   172	        OR o.visibility = 'public'
   173	      )
   174	    ORDER BY (et.organization_id = ${organizationId}) DESC, et.id ASC
   175	    LIMIT 1
   176	  `;
   177	  if (rows.length === 0) return null;
   178	  if (rows[0].backing_sql) return null;
   179	  return Number(rows[0].id);
   180	}
   181	
   182	/**
   183	 * How many readable numeric suffixes (`-2`, `-3`, …) to try before falling back
   184	 * to a guaranteed-unique identifier-derived slug. Keeps slugs human-friendly
   185	 * while guaranteeing the insert terminates.
   186	 */
   187	const SLUG_DISAMBIGUATION_ATTEMPTS = 5;
   188	
   189	/**
   190	 * Insert the child entity, tolerating a slug collision on
   191	 * `entities_slug_parent_unique (organization_id, COALESCE(parent_id,0), slug)`.
   192	 * Two keyed rows can slugify to the same base slug, and the slug can clash with
   193	 * a pre-existing sibling. A raw INSERT would then throw 23505 and — because
   194	 * promotion runs inside the window-completion transaction — roll the whole
   195	 * completion back; since the slug is deterministic, every retry re-hits it and
   196	 * the window is permanently poison-pilled. The entity's real identity is its
   197	 * `watcher_key` claim, so the slug is cosmetic: retry with `-2`, `-3`, … and
   198	 * finally an identifier-derived suffix (unique per watcher+key). Each attempt is
   199	 * savepoint-isolated so a failed INSERT doesn't abort the outer transaction.
   200	 */
   201	async function insertEntityWithUniqueSlug(params: {
   202	  tx: DbClient;
   203	  organizationId: string;
   204	  entityTypeId: number;
   205	  parentEntityId: number | null;
   206	  name: string;
   207	  baseSlug: string;
   208	  identifier: string;
   209	  metadata: Record<string, unknown>;
   210	  createdBy: string;
   211	}): Promise<number> {
   212	  const { tx } = params;
   213	  const insertWithSlug = (slug: string) =>
   214	    tx.savepoint(
   215	      (sp) => sp<{ id: number | string }>`
   216	        INSERT INTO entities (
   217	          organization_id, entity_type_id, name, slug, parent_id, metadata,
   218	          created_by, created_at, updated_at
   219	        ) VALUES (
   220	          ${params.organizationId}, ${params.entityTypeId}, ${params.name}, ${slug},
   221	          ${params.parentEntityId}, ${tx.json(params.metadata)}, ${params.createdBy},
   222	          current_timestamp, current_timestamp
   223	        )
   224	        RETURNING id
   225	      `
   226	    );
   227	
   228	  for (let attempt = 1; attempt <= SLUG_DISAMBIGUATION_ATTEMPTS; attempt++) {
   229	    const slug = attempt === 1 ? params.baseSlug : `${params.baseSlug}-${attempt}`;
   230	    try {
   231	      const inserted = await insertWithSlug(slug);
   232	      return Number(inserted[0].id);
   233	    } catch (err) {
   234	      if (isUniqueViolation(err, 'entities_slug_parent_unique')) continue;
   235	      throw err;
   236	    }
   237	  }
   238	  // Readable suffixes exhausted: the identifier is unique per (watcher, key), so
   239	  // this slug is collision-free among promotions (and effectively so against any
   240	  // sibling). A final failure here propagates to the per-row guard in the loop.
   241	  const inserted = await insertWithSlug(`${params.baseSlug}-${slugify(params.identifier)}`);
   242	  return Number(inserted[0].id);
   243	}
   244	
   245	/**
   246	 * Upsert a child entity by stable key. Returns its id and whether it was newly
   247	 * created. Idempotent across re-runs / concurrent replicas via the
   248	 * `entity_identities` live-unique index on (org, namespace, identifier). Slug
   249	 * collisions are disambiguated by `insertEntityWithUniqueSlug` (the stable key,
   250	 * not the slug, is the identity).
   251	 */
   252	async function upsertKeyedEntity(params: {
   253	  tx: DbClient;
   254	  organizationId: string;
   255	  entityTypeId: number;
   256	  entityTypeSlug: string;
   257	  parentEntityId: number | null;
   258	  identifier: string;
   259	  name: string;
   260	  baseSlug: string;
   261	  metadata: Record<string, unknown>;
   262	  /** Extracted entity field values to sync into metadata (excludes the stable key). */
   263	  fieldValues: Record<string, unknown>;
   264	  createdBy: string;
   265	  /** Watcher whose run is promoting this entity — used for per-principal policy. */
   266	  watcherId: number;
   267	  /**
   268	   * The agent that owns this watcher (watchers.agent_id). The gate resolves the
   269	   * principal to this agent id so the agent's own envelope binds the watcher's
   270	   * writes; null when the watcher row is missing (see watcherOwnerResolved).
   271	   */
   272	  watcherAgentId: string | null;
   273	  /**
   274	   * False iff the watcher row was gone when we resolved its owner — the gate then
   275	   * fails closed (deny) rather than promote under no agent envelope.
   276	   */
   277	  watcherOwnerResolved: boolean;
   278	  /** Org policy: creates of this type queue an approval instead of inserting. */
   279	  createNeedsApproval: boolean;
   280	}): Promise<{
   281	  entityId: number;
   282	  created: boolean;
   283	  blocked: Record<string, BlockedChange>;
   284	  /** Fields the watcher actually wrote inline (auto-applied), old→new. */
   285	  applied: Record<string, AppliedChange>;
   286	  blockedCreate: boolean;
   287	  deniedUpdate?: true;
   288	}> {
   289	  const { tx, organizationId, identifier } = params;
   290	
   291	  // 1. Existing identity → reuse its entity (the idempotent fast path), and SYNC the
   292	  //    freshly-extracted field values into it honoring human ownership AND the org's
   293	  //    update policy: un-gated fields are written; human-owned or policy-gated
   294	  //    fields are returned as `blocked` (the caller queues an approval) and never
   295	  //    overwritten inline.
   296	  const existing = await tx<{ entity_id: number | string }>`
   297	    SELECT ei.entity_id
   298	    FROM entity_identities ei
   299	    JOIN entities e ON e.id = ei.entity_id
   300	    WHERE ei.organization_id = ${organizationId}
   301	      AND ei.namespace = ${WATCHER_KEY_NAMESPACE}
   302	      AND ei.identifier = ${identifier}
   303	      AND ei.deleted_at IS NULL
   304	      AND e.deleted_at IS NULL
   305	    LIMIT 1
   306	  `;
   307	  if (existing.length > 0) {
   308	    const entityId = Number(existing[0].entity_id);
   309	    // Owners are 'none' here on purpose: human ownership is enforced inside the
   310	    // merge itself; the gate only adds the org policy's field gates on top.
   311	    const decision = await runMutationGate({
   312	      action: 'update',
   313	      organizationId,
   314	      // The watcher is the acting principal (its OWN rows bind); its owning agent
   315	      // is folded in as the ancestor via `ownerAgentId` so the agent's envelope
   316	      // ALSO binds — max-restrictive, so the agent can tighten but a watcher-
   317	      // specific restriction is never loosened away.
   318	      principalKind: 'watcher',
   319	      sql: tx,
   320	      attribution: ApprovalAttribution.Behavior,
   321	      watcherId: params.watcherId,
   322	      principalId: mutationPrincipalId({ watcherId: params.watcherId }),
   323	      ownerAgentId: params.watcherAgentId,
   324	      ownerResolved: params.watcherOwnerResolved,
   325	      entityTypeSlug: params.entityTypeSlug,
   326	      entityId,
   327	      fields: Object.fromEntries(
   328	        Object.keys(params.fieldValues).map((field) => [field, 'none' as const])
   329	      ),
   330	    });
   331	    // Fail CLOSED on a deny: apply nothing and return a modeled policy outcome.
   332	    // Unexpected persistence errors still throw and roll back the completion.
   333	    if (decision.outcome === 'deny') {
   334	      return {
   335	        entityId,
   336	        created: false,
   337	        blocked: {},
   338	        applied: {},
   339	        blockedCreate: false,
   340	        deniedUpdate: true,
   341	      };
   342	    }
   343	    const requireApproval = [...decision.requireApproval];
   344	    const merge = await mergeEntityFields({
   345	      tx,
   346	      entityId,
   347	      fields: params.fieldValues,
   348	      source: 'watcher',
   349	      actorId: null,
   350	      requireApproval,
   351	    });
   352	    return {
   353	      entityId,
   354	      created: false,
   355	      blocked: merge.blocked,
   356	      applied: merge.applied,
   357	      blockedCreate: false,
   358	    };
   359	  }
   360	
   361	  // Org policy holds creates of this type for approval — no insert, no identity
   362	  // claim. The caller queues a durable create proposal post-commit; when it is
   363	  // approved and re-promoted, the identity claim above dedupes as usual.
   364	  if (params.createNeedsApproval) {
   365	    return { entityId: 0, created: false, blocked: {}, applied: {}, blockedCreate: true };
   366	  }
   367	
   368	  // 2. Create the entity (sequence-allocated id — multi-replica safe),
   369	  //    tolerating a slug collision so promotion can never poison-pill the window.
   370	  const entityId = await insertEntityWithUniqueSlug({
   371	    tx,
   372	    organizationId,
   373	    entityTypeId: params.entityTypeId,
   374	    parentEntityId: params.parentEntityId,
   375	    name: params.name,
   376	    baseSlug: params.baseSlug,
   377	    identifier,
   378	    metadata: params.metadata,
   379	    createdBy: params.createdBy,
   380	  });
   381	
   382	  // 3. Claim the stable key. ON CONFLICT DO NOTHING against the live-unique
   383	  //    index: if a concurrent completion already claimed it, our insert is a
   384	  //    no-op and we resolve the winner instead.
   385	  const claimed = await tx<{ entity_id: number | string }>`
   386	    INSERT INTO entity_identities (
   387	      organization_id, entity_id, namespace, identifier, source_connector
   388	    ) VALUES (
   389	      ${organizationId}, ${entityId}, ${WATCHER_KEY_NAMESPACE}, ${identifier}, 'watcher'
   390	    )
   391	    ON CONFLICT (organization_id, namespace, identifier) WHERE deleted_at IS NULL
   392	    DO NOTHING
   393	    RETURNING entity_id
   394	  `;
   395	  if (claimed.length > 0) {
   396	    return { entityId, created: true, blocked: {}, applied: {}, blockedCreate: false };
   397	  }
   398	
   399	  // Lost the race: another live transaction already claimed this key. Resolve
   400	  // the winner, then drop the entity we just created so it doesn't linger as an
   401	  // orphaned (identity-less) duplicate child under the parent.
   402	  const winner = await tx<{ entity_id: number | string }>`
   403	    SELECT entity_id
   404	    FROM entity_identities
   405	    WHERE organization_id = ${organizationId}
   406	      AND namespace = ${WATCHER_KEY_NAMESPACE}
   407	      AND identifier = ${identifier}
   408	      AND deleted_at IS NULL
   409	    LIMIT 1
   410	  `;
   411	  if (winner.length > 0) {
   412	    // Safe hard delete: this entity is brand-new in THIS transaction — nothing
   413	    // references it yet (no identity, children, events, or relationships), and
   414	    // entities' only blocking FK is `parent_id ON DELETE RESTRICT`, which can't
   415	    // fire on a freshly-created leaf.
   416	    await tx`
   417	      DELETE FROM entities
   418	      WHERE id = ${entityId} AND organization_id = ${organizationId}
   419	    `;
   420	    return {
   421	      entityId: Number(winner[0].entity_id),
   422	      created: false,
   423	      blocked: {},
   424	      applied: {},
   425	      blockedCreate: false,
   426	    };
   427	  }
   428	  // Extremely unlikely: the conflicting claim was tombstoned between our INSERT
   429	  // and this re-read. Keep our entity as the canonical one.
   430	  return { entityId, created: true, blocked: {}, applied: {}, blockedCreate: false };
   431	}
   432	
   433	/**
   434	 * Promote every row in one named entity output into a child entity.
   435	 * The extraction schema requires every stable-key component, and
   436	 * `computeStableKey` preserves exact scalar identity rather than display
   437	 * normalization. Duplicate exact keys and unexpected persistence errors fail
   438	 * the completion transaction: declared outputs are an atomic contract, not a
   439	 * best-effort side channel that may silently lose rows.
   440	 */
   441	export async function promoteBehaviorEntityOutput(
   442	  params: PromoteKeyedEntitiesParams
   443	): Promise<PromoteKeyedEntitiesResult> {
   444	  const {
   445	    tx,
   446	    extractedData,
   447	    outputName,
   448	    output,
   449	    watcherId,
   450	    organizationId,
   451	    windowId,
   452	    parentEntityId,
   453	    validContentIds,
   454	  } = params;
   455	  let droppedCitations = 0;
   456	  const result: PromoteKeyedEntitiesResult = {
   457	    promoted: 0,
   458	    created: 0,
   459	    deferred: [],
   460	    changes: [],
   461	  };
   462	
   463	  const rows = extractedData[outputName];
   464	  if (!Array.isArray(rows) || rows.length === 0) return result;
   465	
   466	  const entityTypeSlug = output.entity.trim();
   467	  const entityTypeId = await resolveEntityTypeId(tx, organizationId, entityTypeSlug);
   468	  if (entityTypeId == null) {
   469	    logger.warn(
   470	      { watcherId, organizationId, entityTypeSlug, outputName },
   471	      '[promote-keyed-entities] target entity type not found (or derived) — skipping promotion'
   472	    );
   473	    return result;
   474	  }
   475	
   476	  const createdBy = await resolveEntityCreator(tx, organizationId, params.createdBy);
   477	  if (createdBy == null) {
   478	    logger.warn(
   479	      { watcherId, organizationId },
   480	      '[promote-keyed-entities] no live user to attribute created entities to — skipping promotion'
   481	    );
   482	    return result;
   483	  }
   484	
   485	  // A watcher IS an agent's autonomous mode: resolve the owning agent so its
   486	  // write envelope binds these promotions (watchers.agent_id is NOT NULL). The
   487	  // principal resolves to the agent id — the same id the agent uses when acting
   488	  // attended — and mode 'autonomous' lets the agent set a stricter watcher-only
   489	  // envelope. Without this, an agent's own delete=deny would NOT bind its own
   490	  // watcher (the write would fall through to the looser org default).
   491	  const watcherOwner = await resolveWatcherOwner(tx, watcherId, organizationId);
   492	
   493	  // Gate decision for creates of this type (watchers are never human): resolved
   494	  // once per promotion — every row in this window is the same entity type, so
   495	  // one create decision governs them all. We only read the outcome here (the
   496	  // probe's deferral is discarded); each held-back row builds its own deferral
   497	  // below. Fail CLOSED: anything but an explicit 'allow' skips inline creation,
   498	  // and only a 'defer' queues an approval — a 'deny' creates nothing at all.
   499	  const createGate = await runMutationGate({
   500	    action: 'create',
   501	    organizationId,
   502	    // The watcher is the acting principal (its OWN rows bind, e.g. a watcher-
   503	    // specific deny). Its owning agent is folded in as the ancestor via
   504	    // `ownerAgentId` so the agent's envelope ALSO binds — max-restrictive, so
   505	    // the agent envelope can tighten but a watcher-specific restriction can only
   506	    // tighten further, never be loosened away.
   507	    principalKind: 'watcher',
   508	    sql: tx,
   509	    attribution: ApprovalAttribution.Behavior,
   510	    watcherId,
   511	    principalId: mutationPrincipalId({ watcherId }),
   512	    ownerAgentId: watcherOwner.ownerAgentId,
   513	    ownerResolved: watcherOwner.resolved,
   514	    entityTypeSlug,
   515	    entityData: { entity_type: entityTypeSlug, name: '' },
   516	    proposal: {},
   517	  });
   518	  const createNeedsApproval = createGate.outcome !== 'allow';
   519	  if (createGate.outcome === 'deny') {
   520	    logger.warn(
   521	      { watcherId, organizationId, entityTypeSlug, reason: createGate.reason },
   522	      '[promote-keyed-entities] mutation gate denied creates for this type — new rows will be skipped'
   523	    );
   524	  }
   525	
   526	  // A declared output is a complete result, so duplicate identities are an
   527	  // authoring error. Silently keeping the first row would make output depend on
   528	  // array order and discard potentially different field values.
   529	  const seenKeys = new Set<string>();
   530	  const keyedRows = rows.map((row) => {
   531	    const entityRecord = row as Record<string, unknown>;
   532	    const stableKey = computeStableKey(entityRecord, output.key);
   533	    if (seenKeys.has(stableKey)) {
   534	      throw new Error(
   535	        `Behavior output "${outputName}" contains a duplicate exact key (${stableKey})`
   536	      );
   537	    }
   538	    seenKeys.add(stableKey);
   539	    return { entityRecord, stableKey };
   540	  });
   541	
   542	  for (const { entityRecord, stableKey } of keyedRows) {
   543	    const identifier = formatBehaviorEntityIdentity(
   544	      watcherId,
   545	      outputName,
   546	      entityTypeSlug,
